import { cn } from "@/lib/utils";

export const ORDER_STEPS = ["PAID", "PROCESSING", "SHIPPED", "DELIVERED"] as const;

export const ORDER_STATUSES = ["PENDING_PAYMENT", "PAID", "PROCESSING", "SHIPPED", "DELIVERED", "CANCELLED", "PAYMENT_FAILED", "REFUNDED"] as const;

const STYLES: Record<string, string> = {
  PENDING_PAYMENT: "bg-warn/15 text-warn",
  PAID: "bg-blue-100 text-blue-800",
  PROCESSING: "bg-indigo-100 text-indigo-800",
  SHIPPED: "bg-brass-light text-brass",
  DELIVERED: "bg-success/15 text-success",
  CANCELLED: "bg-line text-ink-soft",
  PAYMENT_FAILED: "bg-danger/10 text-danger",
  REFUNDED: "bg-line text-ink-soft",
};

export function statusLabel(s: string) {
  return s.replace(/_/g, " ").toLowerCase().replace(/^\w/, (c) => c.toUpperCase());
}

export function OrderStatusBadge({ status }: { status: string }) {
  return <span className={cn("badge px-3 py-1", STYLES[status] ?? "bg-line")}>{statusLabel(status)}</span>;
}
